CREATE TYPE public.app_role AS ENUM ('admin', 'user');
CREATE TYPE public.application_status AS ENUM ('Saved','Applied','Interview','Offer','Rejected');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, name text NOT NULL DEFAULT '', skills text[] NOT NULL DEFAULT '{}', services text[] NOT NULL DEFAULT '{}', preferred_countries text[] NOT NULL DEFAULT '{}', work_preference text NOT NULL DEFAULT 'All' CHECK (work_preference IN ('Remote','Hybrid','On-site','All')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_read_own ON public.profiles FOR SELECT TO authenticated USING (id = (select auth.uid()));
CREATE POLICY profiles_update_own ON public.profiles FOR UPDATE TO authenticated USING (id = (select auth.uid())) WITH CHECK (id = (select auth.uid()));
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY roles_read_own ON public.user_roles FOR SELECT TO authenticated USING (user_id = (select auth.uid()));
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid, public.app_role) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.has_role(uuid, public.app_role) TO authenticated, service_role;
CREATE TABLE public.sources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, platform text NOT NULL CHECK (platform IN ('Facebook','LinkedIn','Instagram','TikTok','Reddit','Web')), enabled boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.sources TO authenticated;
GRANT ALL ON public.sources TO service_role;
ALTER TABLE public.sources ENABLE ROW LEVEL SECURITY;
CREATE POLICY sources_read ON public.sources FOR SELECT TO authenticated USING (enabled OR public.has_role((select auth.uid()),'admin'));
CREATE POLICY sources_admin ON public.sources FOR ALL TO authenticated USING (public.has_role((select auth.uid()),'admin')) WITH CHECK (public.has_role((select auth.uid()),'admin'));
CREATE TABLE public.opportunities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_id uuid REFERENCES public.sources(id) ON DELETE SET NULL, title text NOT NULL CHECK(length(trim(title)) > 0), company text NOT NULL DEFAULT '', summary text NOT NULL DEFAULT '', country text, work_location text NOT NULL DEFAULT 'All' CHECK(work_location IN ('Remote','Hybrid','On-site','All')), opportunity_type text NOT NULL DEFAULT 'Contract', skills text[] NOT NULL DEFAULT '{}', url text, published boolean NOT NULL DEFAULT false, posted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.opportunities TO authenticated;
GRANT ALL ON public.opportunities TO service_role;
ALTER TABLE public.opportunities ENABLE ROW LEVEL SECURITY;
CREATE POLICY opportunities_read ON public.opportunities FOR SELECT TO authenticated USING (published OR public.has_role((select auth.uid()),'admin'));
CREATE POLICY opportunities_admin ON public.opportunities FOR ALL TO authenticated USING (public.has_role((select auth.uid()),'admin')) WITH CHECK (public.has_role((select auth.uid()),'admin'));
CREATE TABLE public.saved_opportunities (user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, opportunity_id uuid NOT NULL REFERENCES public.opportunities(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,opportunity_id));
GRANT SELECT, INSERT, DELETE ON public.saved_opportunities TO authenticated;
GRANT ALL ON public.saved_opportunities TO service_role;
ALTER TABLE public.saved_opportunities ENABLE ROW LEVEL SECURITY;
CREATE POLICY saves_read ON public.saved_opportunities FOR SELECT TO authenticated USING (user_id = (select auth.uid()));
CREATE POLICY saves_create ON public.saved_opportunities FOR INSERT TO authenticated WITH CHECK (user_id = (select auth.uid()) AND EXISTS (SELECT 1 FROM public.opportunities o WHERE o.id = opportunity_id AND o.published));
CREATE POLICY saves_delete ON public.saved_opportunities FOR DELETE TO authenticated USING (user_id = (select auth.uid()));
CREATE TABLE public.tracked_applications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, opportunity_id uuid REFERENCES public.opportunities(id) ON DELETE SET NULL, title text NOT NULL CHECK(length(trim(title)) > 0), company text NOT NULL DEFAULT '', status public.application_status NOT NULL DEFAULT 'Saved', notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id, opportunity_id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.tracked_applications TO authenticated;
GRANT ALL ON public.tracked_applications TO service_role;
ALTER TABLE public.tracked_applications ENABLE ROW LEVEL SECURITY;
CREATE POLICY tracker_owner ON public.tracked_applications FOR ALL TO authenticated USING (user_id = (select auth.uid())) WITH CHECK (user_id = (select auth.uid()) AND (opportunity_id IS NULL OR EXISTS (SELECT 1 FROM public.opportunities o WHERE o.id = opportunity_id AND o.published)));
CREATE INDEX tracked_applications_user_idx ON public.tracked_applications(user_id);
CREATE TABLE public.alert_preferences (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, name text NOT NULL CHECK(length(trim(name)) > 0), keywords text NOT NULL DEFAULT '', countries text[] NOT NULL DEFAULT '{}', work_preference text NOT NULL DEFAULT 'All' CHECK(work_preference IN ('Remote','Hybrid','On-site','All')), enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.alert_preferences TO authenticated;
GRANT ALL ON public.alert_preferences TO service_role;
ALTER TABLE public.alert_preferences ENABLE ROW LEVEL SECURITY;
CREATE POLICY alerts_owner ON public.alert_preferences FOR ALL TO authenticated USING (user_id = (select auth.uid())) WITH CHECK (user_id = (select auth.uid()));
CREATE INDEX alert_preferences_user_idx ON public.alert_preferences(user_id);
CREATE FUNCTION public.create_account_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(id,name) VALUES (NEW.id, COALESCE(NEW.raw_user_meta_data->>'name','')); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.create_account_profile() FROM PUBLIC, anon, authenticated;
CREATE TRIGGER on_account_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_account_profile();